// Original geometric illustrations. These people represent neither customers nor personality types.
function person(x,y,{skin,hair,coat,shade,trousers,pose=0,elder=false,scale=1}){return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cx="42" cy="219" rx="40" ry="5" fill="#244c6810"/><path d="M18 130H67L61 211H45L40 156L34 211H17Z" fill="${trousers}"/><path d="M17 208H35V217H9V213ZM45 208H61L70 216H45Z" fill="#244154"/><path d="M29 59V45H53V61L42 76Z" fill="${skin}"/><path d="M13 72L29 60L42 70L54 60L72 72L66 139H16Z" fill="${coat}"/><path d="M42 70L54 60L72 72L66 139H42Z" fill="${shade}"/><path d="M28 61L42 70L34 88L22 67ZM54 61L42 70L49 87L61 66Z" fill="#ffffff44"/><path d="M42 70V139" stroke="#ffffff66"/><path d="M23 17L40 7L61 18L59 44L45 59L29 50L22 34Z" fill="${skin}"/><path d="M40 8L61 18L59 44L45 59L41 35Z" fill="#00000009"/><path d="M22 34L17 19L26 6L46 0L65 13L63 29L55 17L37 23L27 20L26 38Z" fill="${hair}"/>${elder?'<path d="M27 30H38V39H27ZM45 30H56V39H45ZM38 33H45" fill="none" stroke="#456276" stroke-width="1.7"/>':'<path d="M31 32H34M49 32H52" stroke="#3b4146" stroke-width="1.8"/>'}<path d="M36 46L46 47" stroke="#714e44" stroke-width="1.4"/>${pose===1?`<path d="M15 73L5 101L33 119L38 109L20 96L29 77Z" fill="${coat}"/><path d="M71 73L91 59L89 39L98 36L105 67L79 91Z" fill="${shade}"/><path d="M89 39L87 27L91 25L95 33L99 27L103 30L98 42Z" fill="${skin}"/><path d="M33 109L45 112L44 120L33 119Z" fill="${skin}"/>`:pose===2?`<path d="M14 73L0 114L26 125L30 115L17 109L29 78Z" fill="${coat}"/><path d="M70 73L86 113L60 124L56 114L70 108L56 78Z" fill="${shade}"/><path d="M25 113L39 113L39 124L26 125ZM59 113L47 112L47 124L60 124Z" fill="${skin}"/><path d="M30 99L44 103L58 99V125L44 129L30 125Z" fill="#fffbec"/><path d="M44 103V129" stroke="#d2bf91"/>`:`<path d="M13 73L3 123L14 126L29 77Z" fill="${coat}"/><path d="M72 73L82 121L71 126L55 77Z" fill="${shade}"/><path d="M3 121L14 124L13 136L5 137ZM71 124L82 120L84 133L77 138Z" fill="${skin}"/>`}</g>`}
export function peopleLandscape(){return `<svg viewBox="0 0 1200 280" class="professional-people" aria-hidden="true" focusable="false"><path d="M0 240L0 143L92 187L189 77L290 176L372 120L455 202L565 152L660 203L774 86L886 171L992 112L1107 182L1200 142V280H0Z" fill="#f0f7fb"/><path d="M0 240L189 77L152 218Z" fill="#e5f1f9"/><path d="M189 77L290 176L152 218Z" fill="#f7fbfd"/><path d="M660 203L774 86L739 227Z" fill="#e0eef7"/><path d="M774 86L886 171L739 227Z" fill="#edf6fb"/><path d="M886 171L992 112L1045 243Z" fill="#e8f2f9"/><path d="M0 263L177 229L303 260L442 233L605 264L780 239L968 262L1091 230L1200 250V280H0Z" fill="#f5f8f9"/><circle cx="600" cy="122" r="83" fill="#fff6df"/><path d="M533 126L584 81L614 106L666 57" fill="none" stroke="#ebd59d" stroke-width="2"/><path d="M651 58L666 57L664 73" fill="none" stroke="#ebd59d" stroke-width="2"/>${person(256,51,{skin:'#be8567',hair:'#254653',coat:'#73a3bc',shade:'#5486a1',trousers:'#3b596b',pose:2,scale:.91})}${person(411,24,{skin:'#e7b99d',hair:'#35475a',coat:'#7b8ab0',shade:'#5c6b96',trousers:'#344459',pose:1})}${person(602,19,{skin:'#c28f70',hair:'#d2d6d7',coat:'#c8a75f',shade:'#b28c45',trousers:'#485866',elder:true,scale:1.02})}${person(788,51,{skin:'#936550',hair:'#273d49',coat:'#6a9385',shade:'#4f786d',trousers:'#334d54',pose:2,scale:.92})}<path d="M116 251V211M116 234L100 217M116 223L132 204M1075 252V211M1075 235L1059 220M1075 225L1092 210" fill="none" stroke="#a9c5ca" stroke-width="2"/><path d="M100 217L97 204L108 210ZM132 204L135 192L124 198ZM1059 220L1057 206L1067 213ZM1092 210L1097 197L1084 204Z" fill="#b7cdd2"/></svg>`}
export function benefitIcon(i){const paths=[`<circle cx="26" cy="25" r="15"/><path d="M37 37L50 50M20 25L25 30L33 20"/>`,`<path d="M9 13H38V34H23L15 41V34H9ZM28 39V45H39L48 51V45H53V26H43"/>`,`<rect x="10" y="18" width="43" height="32" rx="3"/><path d="M23 18V10H40V18M10 31H53M27 31V36H36V31"/>`][i];return `<svg class="potential-icon" viewBox="0 0 64 64" aria-hidden="true" focusable="false"><path d="M5 5H59V59H5Z" fill="${['#eff6fa','#f4f1f8','#fbf6e9'][i]}" stroke="none"/><g fill="none" stroke="${['#5795b8','#8d80a6','#b39652'][i]}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths}</g></svg>`}
